import { ArrowLeft, ArrowRight, ArrowUpRight, BookmarkPlus, ChevronDown, Clock3, Download, Eye, Filter, Grid2X2, Heart, ImageIcon, Instagram, Languages, List, ListPlus, Mail, MapPin, MessageSquareText, Music2, Puzzle, Search, Send, ShieldCheck, SlidersHorizontal, Sparkles, TrendingUp, Upload, Users, X, Youtube } from "lucide-react";
