const L = {
  title: { zh: "达人中心", en: "Creators" }, subtitle: { zh: "搜索、筛选和管理适合品牌合作的达人。", en: "Discover, qualify, and manage creators for your brand collaborations." },
  marketplace: { zh: "达人广场", en: "Creator Marketplace" }, private: { zh: "私有达人", en: "Private Creators" }, ai: { zh: "AI 搜索", en: "AI Search" }, keyword: { zh: "关键词搜索", en: "Keyword Search" },
  marketplaceSubtitle: { zh: "探索与筛选适合品牌合作的达人。", en: "Discover and qualify creators for your brand collaborations." },
  privateSubtitle: { zh: "管理品牌已沉淀的私域达人与分组。", en: "Organize your private creator relationships and groups." },
  skillTitle: { zh: "达人发现 Skill", en: "Creator Discovery Skill" }, skillDesc: { zh: "让团队成员通过自然语言快速定位合适达人，并复用你的筛选逻辑。", en: "Help your team find the right creators in natural language using your matching logic." },
  chromeTitle: { zh: "Chrome 插件", en: "Chrome Extension" }, chromeDesc: { zh: "浏览社媒时一键识别达人、保存资料并加入私域达人库。", en: "Identify creators, save profiles, and add them to your private pool while browsing social platforms." },
  explore: { zh: "查看入口", en: "Explore" },
  aiPlaceholder: { zh: "描述你想找的达人，例如：美国美妆类、粉丝 10 万以上、互动率高且内容调性高级", en: "Describe your ideal creators — e.g. US beauty creators with 100K+ followers, strong engagement, and a premium visual style" }, keywordPlaceholder: { zh: "搜索达人姓名、账号、简介或类型", en: "Search by creator name, username, bio or category" },
  aiHint: { zh: "AI 会理解你的需求，并自动转化为关键词与筛选条件。", en: "AI understands your request and turns it into keywords and filters." }, search: { zh: "搜索", en: "Search" }, filters: { zh: "筛选", en: "Filters" }, platform: { zh: "全部平台", en: "All platforms" }, country: { zh: "全部国家 / 地区", en: "All countries" }, followers: { zh: "任意粉丝量", en: "Any follower size" }, category: { zh: "全部类型", en: "All categories" },
  creators: { zh: "位达人", en: "creators" }, resultsHint: { zh: "达人历史合作、受众和表现数据会随平台变化。", en: "Creator history is shared; audience and performance remain platform-specific." }, sort: { zh: "粉丝量：从高到低", en: "Followers: High to low" }, location: { zh: "美国", en: "United States" }, collabs: { zh: "合作次数", en: "Known collaborations" }, delivery: { zh: "准时交付", en: "On-time delivery" }, view: { zh: "查看详情", en: "View details" }, add: { zh: "加入候选", en: "Add to shortlist" }, added: { zh: "已加入候选", en: "Shortlisted" }, followersLabel: { zh: "粉丝", en: "Followers" }, views: { zh: "平均播放", en: "Avg. views" }, engagement: { zh: "互动率", en: "Engagement" }, audience: { zh: "受众画像", en: "Audience profile" }, works: { zh: "近期内容", en: "Recent works" },
  outreachTitle: { zh: "建联中心", en: "Outreach Center" }, outreachSubtitle: { zh: "按营销活动管理达人沟通记录与下一步跟进。", en: "Manage creator conversations and next steps by campaign." },
} as const;

export function CreatorMarketplacePage() {
  const l = useLoc();
  const productMode = useUIStore((state) => state.productMode);
  const sectionTab = useUIStore((state) => state.discoverSections.creators);
  const setDiscoverSection = useUIStore((state) => state.setDiscoverSection);
  const params = useSearchParams();
  const [campaignView, setCampaignView] = useState<"marketplace" | "private">(params.get("tab") === "private" ? "private" : "marketplace");
  const [discoverDirectoryTab, setDiscoverDirectoryTab] = useState<"marketplace" | "private">("marketplace");
  const [detailCreatorId, setDetailCreatorId] = useState<string | null>(null);
  const [mode, setMode] = useState<"ai" | "keyword">("ai"); const [query, setQuery] = useState(""); const [platform, setPlatform] = useState("all"); const [shortlisted, setShortlisted] = useState<string[]>([]); const [coverName, setCoverName] = useState("");
  const results = useMemo(() => creators.filter((c) => (!query || `${c.name} ${c.handle} ${c.platform}`.toLowerCase().includes(query.toLowerCase())) && (platform === "all" || c.platform === platform)), [query, platform]);
  const isDiscover = productMode === "discover";
  const isCampaignPrivate = campaignView === "private";
  const detailCreator = creators.find((creator) => creator.id === detailCreatorId) ?? null;
  useEffect(() => { if (isDiscover && (sectionTab === "discovery" || sectionTab === "private")) setDiscoverDirectoryTab(sectionTab === "private" ? "private" : "marketplace"); }, [isDiscover, sectionTab]);
  if (isDiscover && (sectionTab === "discovery" || sectionTab === "private")) {
    return <CreatorDirectoryPage activeTab={discoverDirectoryTab} onTabChange={(tab) => { setDiscoverDirectoryTab(tab); setDiscoverSection("creators", tab === "marketplace" ? "discovery" : "private"); }} query={query} setQuery={setQuery} platform={platform} setPlatform={setPlatform} results={results} shortlisted={shortlisted} setShortlisted={setShortlisted} detailCreator={detailCreator} setDetailCreatorId={setDetailCreatorId} />;
  }
  if (isDiscover && (sectionTab === "ai-search" || sectionTab === "cover-search")) {
    return <CreatorSearchWorkspace variant={sectionTab} query={query} setQuery={setQuery} platform={platform} setPlatform={setPlatform} coverName={coverName} setCoverName={setCoverName} results={results} shortlisted={shortlisted} setShortlisted={setShortlisted} detailCreator={detailCreator} setDetailCreatorId={setDetailCreatorId} />;
  }
  if (isDiscover && sectionTab === "outreach") return <OutreachView />;
  return <main className="min-h-full bg-white px-6 py-8 lg:px-10"><div className="mx-auto w-full max-w-[1320px]">
    {isDiscover ? <header className="flex flex-wrap items-center justify-between gap-4"><h1 className="flex h-14 items-center text-[30px] font-bold tracking-[-0.035em] text-navy">{l(sectionTab === "discovery" ? { zh: "达人发现", en: "Discovery" } : sectionTab === "outreach" ? L.outreachTitle : L.private)}</h1>{sectionTab === "discovery" && <div className="flex w-full gap-2 sm:w-auto"><ToolEntry icon={<Sparkles className="h-4 w-4" />} tone="pink" title={l(L.skillTitle)} /><ToolEntry icon={<Puzzle className="h-4 w-4" />} tone="teal" title={l(L.chromeTitle)} /></div>}</header> : <header className="flex flex-wrap items-start justify-between gap-5"><div><p className="text-[10px] font-semibold uppercase tracking-[0.12em] text-muted">{l(L.title)}</p><h1 className="mt-1 text-[30px] font-bold tracking-[-0.035em] text-navy">{l(isCampaignPrivate ? { zh: "私域达人", en: "Private Creators" } : L.marketplace)}</h1><p className="mt-1.5 text-[13px] text-slate">{l(isCampaignPrivate ? L.privateSubtitle : L.marketplaceSubtitle)}</p></div><nav className="flex rounded-[10px] border border-border bg-page p-1"><button onClick={() => setCampaignView("marketplace")} className={`rounded-[7px] px-4 py-2 text-[12px] font-semibold ${!isCampaignPrivate ? "bg-white text-brand shadow-sm" : "text-slate"}`}>{l(L.marketplace)}</button><button onClick={() => setCampaignView("private")} className={`rounded-[7px] px-4 py-2 text-[12px] font-semibold ${isCampaignPrivate ? "bg-white text-brand shadow-sm" : "text-slate"}`}>{l({ zh: "私域达人", en: "Private Creators" })}</button></nav></header>}
    {isDiscover && sectionTab === "private" ? <PrivateCreatorsView /> : !isDiscover && isCampaignPrivate ? <section className="mt-7"><PrivatePoolView /></section> : <>
      {!isDiscover && <section className="mt-6 grid gap-3 md:grid-cols-2"><CampaignToolEntry icon={<Sparkles className="h-4 w-4" />} tone="pink" title={l(L.skillTitle)} description={l(L.skillDesc)} action={l(L.explore)} /><CampaignToolEntry icon={<Puzzle className="h-4 w-4" />} tone="teal" title={l(L.chromeTitle)} description={l(L.chromeDesc)} action={l(L.explore)} /></section>}
      <section className="mt-7 rounded-[22px] bg-[#F4F4F5] p-5 sm:p-6"><div className="mb-4 flex gap-1 border-b border-border/50"><Mode active={mode === "ai"} onClick={() => setMode("ai")} icon={<Sparkles className="h-3.5 w-3.5" />}>{l(L.ai)}</Mode><Mode active={mode === "keyword"} onClick={() => setMode("keyword")} icon={<Search className="h-3.5 w-3.5" />}>{l(L.keyword)}</Mode></div><div className="flex gap-3"><div className="relative flex-1">{mode === "ai" ? <Sparkles className="absolute left-5 top-1/2 h-5 w-5 -translate-y-1/2 text-brand" /> : <Search className="absolute left-5 top-1/2 h-5 w-5 -translate-y-1/2 text-slate" />}<input value={query} onChange={(e) => setQuery(e.target.value)} placeholder={l(mode === "ai" ? L.aiPlaceholder : L.keywordPlaceholder)} className="h-[68px] w-full rounded-[16px] border border-transparent bg-white pl-12 pr-12 text-[14px] text-ink shadow-[0_1px_2px_rgba(32,26,70,0.03)] outline-none placeholder:text-muted transition focus:border-brand/15 focus:bg-white focus:shadow-[0_8px_24px_rgba(63,35,142,0.08)]" />{query && <button onClick={() => setQuery("")} className="absolute right-4 top-1/2 -translate-y-1/2 text-muted"><X className="h-4 w-4" /></button>}</div><Button className="h-[68px] px-6">{l(L.search)}</Button></div>{mode === "ai" ? <p className="mt-3 text-[11px] text-muted">{l(L.aiHint)}</p> : <div className="mt-4 flex flex-wrap items-center gap-2.5"><span className="mr-1 flex items-center gap-1.5 text-[11px] font-medium text-slate"><Filter className="h-3.5 w-3.5 text-slate" />{l(L.filters)}</span><Dropdown value={platform} onChange={setPlatform} options={[{ value: "all", label: l(L.platform) }, { value: "TikTok", label: "TikTok" }, { value: "Instagram", label: "Instagram" }, { value: "RedNote", label: "RedNote" }]} /><StaticDrop label={l(L.country)} /><StaticDrop label={l(L.followers)} /><StaticDrop label={l(L.category)} /></div>}</section>
      <div className="mt-8 flex flex-wrap items-center gap-3"><strong className="text-[17px] font-semibold text-ink">{results.length} {l(L.creators)}</strong><span className="text-[11px] text-muted">{l(L.resultsHint)}</span><button className="ml-auto flex h-9 items-center gap-2 rounded-[10px] bg-[#F4F4F5] px-3 text-[11px] text-slate transition hover:bg-[#ECECEF]">{l(L.sort)}<ChevronDown className="h-3.5 w-3.5" /></button></div>
      {isDiscover ? <DiscoverCreatorTable creators={results} shortlisted={shortlisted} onToggle={(creatorId) => setShortlisted((all) => all.includes(creatorId) ? all.filter((id) => id !== creatorId) : [...all, creatorId])} onView={setDetailCreatorId} /> : <div className="mt-4 space-y-2.5">{results.map((creator, index) => <CreatorRow key={creator.id} creator={creator} index={index} selected={shortlisted.includes(creator.id)} onToggle={() => setShortlisted((all) => all.includes(creator.id) ? all.filter((id) => id !== creator.id) : [...all, creator.id])} />)}</div>}
    </>}
    {isDiscover && detailCreator && <CreatorProfileDrawer creator={detailCreator} onClose={() => setDetailCreatorId(null)} />}
  </div></main>;
}

function CreatorDirectoryPage({ activeTab, query, setQuery, setPlatform, shortlisted, setShortlisted, detailCreator, setDetailCreatorId }: { activeTab: "marketplace" | "private"; onTabChange: (tab: "marketplace" | "private") => void; query: string; setQuery: (value: string) => void; platform: string; setPlatform: (value: string) => void; results: typeof creators; shortlisted: string[]; setShortlisted: React.Dispatch<React.SetStateAction<string[]>>; detailCreator: typeof creators[number] | null; setDetailCreatorId: (id: string | null) => void }) {
  const l = useLoc();
  const [activePlatform, setActivePlatform] = useState("Instagram");
  const [activeFilters, setActiveFilters] = useState<Record<string, string>>({});
  const [openFilter, setOpenFilter] = useState<string | null>(null);
  const [view, setView] = useState<"list" | "grid">("list");
  const [sort, setSort] = useState("recommended");
  const isMarketplace = activeTab === "marketplace";
  const allCreators = useMemo(() => creators.filter((creator) => creator.platform === activePlatform && (!query || `${creator.name} ${creator.handle} ${creator.platform}`.toLowerCase().includes(query.toLowerCase()))), [activePlatform, query]);
  useEffect(() => { if (isMarketplace) setPlatform(activePlatform); }, [activePlatform, isMarketplace, setPlatform]);
  const platformOptions = [
    { id: "Instagram", icon: Instagram, tone: "text-[#B84D82]" },
    { id: "TikTok", icon: Music2, tone: "text-[#343342]" },
    { id: "YouTube", icon: Youtube, tone: "text-[#D84A4A]" },
  ];
  const filterOptions = [
    { id: "country", label: l({ zh: "国家 / 地区", en: "Country" }), icon: MapPin, options: ["United States", "United Kingdom", "Canada", "Australia"] },
    { id: "followers", label: l({ zh: "粉丝量", en: "Followers" }), icon: Users, options: ["10K–100K", "100K–500K", "500K+"] },
    { id: "engagement", label: l({ zh: "互动率", en: "Engagement" }), icon: TrendingUp, options: ["ER > 3%", "ER > 5%", "ER > 8%"] },
    { id: "audience", label: l({ zh: "受众", en: "Audience" }), icon: Users, options: [l({ zh: "女性受众 65%+", en: "Women 65%+" }), l({ zh: "男性受众 65%+", en: "Men 65%+" })] },
    { id: "language", label: l({ zh: "语言", en: "Language" }), icon: Languages, options: [l({ zh: "英语", en: "English" }), l({ zh: "中文", en: "Chinese" }), l({ zh: "西班牙语", en: "Spanish" })] },
    { id: "audienceLocation", label: l({ zh: "受众地区", en: "Audience location" }), icon: MapPin, options: [l({ zh: "美国受众", en: "US audience" }), l({ zh: "欧洲受众", en: "Europe audience" })] },
    { id: "audienceAge", label: l({ zh: "受众年龄", en: "Audience age" }), icon: Users, options: ["18–24", "25–34", "35–44"] },
    { id: "views", label: l({ zh: "平均播放量", en: "Average views" }), icon: TrendingUp, options: ["10K+", "50K+", "100K+"] },
    { id: "creatorType", label: l({ zh: "博主类型", en: "Creator type" }), icon: Users, options: [l({ zh: "美妆", en: "Beauty" }), l({ zh: "生活方式", en: "Lifestyle" }), l({ zh: "健身", en: "Fitness" })] },
    { id: "safety", label: l({ zh: "品牌安全", en: "Brand safety" }), icon: ShieldCheck, options: [l({ zh: "已验证", en: "Verified" }), l({ zh: "低风险", en: "Low risk" })] },
    { id: "growth", label: l({ zh: "增长率", en: "Growth rate" }), icon: TrendingUp, options: ["> 10%", "> 20%"] },
    { id: "email", label: l({ zh: "合作邮箱", en: "Email available" }), icon: Mail, options: [l({ zh: "有合作邮箱", en: "Email available" })] },
  ];
  const setFilter = (id: string, value: string) => setActiveFilters((current) => ({ ...current, [id]: value }));
  const clearFilter = (id: string) => setActiveFilters((current) => { const next = { ...current }; delete next[id]; return next; });
  if (!isMarketplace) return <main className="min-h-full bg-white px-6 py-6 lg:px-10"><div className="mx-auto w-full max-w-[1440px]"><PrivateCreatorsView /></div></main>;
  return <main className="min-h-full bg-white px-6 py-6 lg:px-10"><div className="mx-auto w-full max-w-[1440px]">
    <section aria-label={l({ zh: "平台范围", en: "Platform coverage" })} className="flex flex-wrap items-center gap-2">{platformOptions.map(({ id, icon: Icon, tone }) => { const selected = activePlatform === id; return <button key={id} type="button" onClick={() => setActivePlatform(id)} aria-pressed={selected} className={`flex h-10 items-center gap-2 rounded-[8px] px-3 text-[13px] font-medium transition ${selected ? "border border-brand bg-white text-brand" : "text-muted hover:bg-[#F7F7F8] hover:text-slate"}`}><Icon className={`h-4 w-4 ${tone}`} strokeWidth={selected ? 2.2 : 1.8} />{id}</button>; })}</section>
    <form onSubmit={(event) => event.preventDefault()} className="mt-4 flex h-12 w-full items-center rounded-[11px] border border-border bg-white px-4 transition focus-within:border-brand/60 focus-within:ring-4 focus-within:ring-brand/10"><Search className="h-4.5 w-4.5 shrink-0 text-muted" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={l({ zh: "搜索达人、用户名或关键词...", en: "Search creators, usernames or keywords..." })} className="h-full min-w-0 flex-1 bg-transparent px-3 text-[13px] text-ink outline-none placeholder:text-muted" /><button type="submit" className="flex h-9 w-14 items-center justify-center rounded-[8px] bg-brand text-white transition-colors hover:bg-brand-hover focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-brand/30" aria-label={l({ zh: "搜索", en: "Search" })}><Search className="h-4 w-4" /></button></form>
    <section className="mt-4"><div className="flex flex-wrap gap-2">{filterOptions.map((filter) => { const Icon = filter.icon; const selected = activeFilters[filter.id]; return <div key={filter.id} className="relative"><button type="button" onClick={() => setOpenFilter((current) => current === filter.id ? null : filter.id)} className={`flex h-8 items-center gap-1.5 rounded-[8px] px-2.5 text-[12px] transition ${selected ? "bg-[#F1EEFF] text-brand" : "bg-[#F5F5F6] text-slate hover:bg-[#ECECEF] hover:text-ink"}`}><Icon className="h-3.5 w-3.5" /><span>{selected ? `${filter.label} · ${selected}` : filter.label}</span><ChevronDown className="h-3.5 w-3.5" /></button>{openFilter === filter.id && <div className="absolute left-0 top-10 z-30 min-w-48 rounded-[10px] border border-border bg-white p-1.5 shadow-[0_10px_24px_rgba(24,24,27,0.08)]">{filter.options.map((option) => <button key={option} type="button" onClick={() => { setFilter(filter.id, option); setOpenFilter(null); }} className="flex h-8 w-full items-center rounded-[7px] px-2.5 text-left text-[11px] text-slate hover:bg-[#F5F5F6] hover:text-ink">{option}</button>)}</div>}</div>; })}{Object.keys(activeFilters).length > 0 && <button type="button" onClick={() => setActiveFilters({})} className="flex h-8 items-center rounded-[8px] px-2.5 text-[12px] text-slate hover:bg-[#F5F5F6] hover:text-ink">{l({ zh: "清空筛选", en: "Clear filters" })}</button>}</div></section>
    <section className="mt-6"><div className="flex flex-wrap items-center gap-3"><p className="text-[13px] font-medium text-ink">{allCreators.length === 0 ? "0" : ({ Instagram: "12,320", TikTok: "8,940", YouTube: "6,470" }[activePlatform])} {l({ zh: "位达人", en: "creators" })}</p><div className="ml-auto flex items-center gap-2"><label className="flex h-8 items-center gap-1.5 rounded-[8px] bg-[#F5F5F6] px-2.5 text-[11px] text-slate">{l({ zh: "排序：", en: "Sort by:" })}<select value={sort} onChange={(event) => setSort(event.target.value)} className="appearance-none bg-transparent font-medium text-ink outline-none"><option value="recommended">{l({ zh: "综合推荐", en: "Recommended" })}</option><option value="followers">{l({ zh: "粉丝量", en: "Followers" })}</option><option value="engagement">{l({ zh: "互动率", en: "Engagement" })}</option><option value="views">{l({ zh: "平均播放", en: "Average views" })}</option></select><ChevronDown className="h-3.5 w-3.5 text-muted" /></label><div className="flex h-8 items-center gap-0.5 rounded-[8px] bg-[#F5F5F6] p-0.5"><button type="button" onClick={() => setView("list")} className={`flex h-7 w-7 items-center justify-center rounded-[6px] ${view === "list" ? "bg-white text-ink" : "text-muted hover:text-slate"}`} aria-label={l({ zh: "列表视图", en: "List view" })}><List className="h-3.5 w-3.5" /></button><button type="button" onClick={() => setView("grid")} className={`flex h-7 w-7 items-center justify-center rounded-[6px] ${view === "grid" ? "bg-white text-ink" : "text-muted hover:text-slate"}`} aria-label={l({ zh: "网格视图", en: "Grid view" })}><Grid2X2 className="h-3.5 w-3.5" /></button></div></div></div>{view === "list" ? <MarketplaceCreatorTable creators={allCreators} selectedIds={shortlisted} onToggle={(id) => setShortlisted((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id])} onView={setDetailCreatorId} /> : <CreatorDiscoveryGrid creators={allCreators} selectedIds={shortlisted} onToggle={(id) => setShortlisted((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id])} onView={setDetailCreatorId} />}</section>
    {detailCreator && <CreatorProfileDrawer creator={detailCreator} onClose={() => setDetailCreatorId(null)} />}
  </div></main>;
}

function MarketplaceCreatorTable({ creators: rows, selectedIds, onToggle, onView }: { creators: typeof creators; selectedIds: string[]; onToggle: (id: string) => void; onView: (id: string) => void }) {
  const l = useLoc();
  return <div className="mt-3 overflow-x-auto rounded-[12px] border border-border bg-white"><div className="min-w-[920px]">
    <div className="grid grid-cols-[minmax(290px,1.65fr)_150px_170px_145px_145px] items-center border-b border-border bg-[#F7F7F8] px-5 py-3 text-[9px] font-medium uppercase tracking-[0.07em] text-muted"><span>{l({ zh: "达人", en: "Creator" })}</span><span>{l({ zh: "粉丝量", en: "Followers" })}</span><span>{l({ zh: "受众", en: "Audience" })}</span><span>{l({ zh: "互动率", en: "Engagement" })}</span><span className="text-right">{l({ zh: "操作", en: "Actions" })}</span></div>
    {rows.length === 0 ? <div className="px-5 py-16 text-center"><p className="text-[13px] font-medium text-ink">{l({ zh: "未找到达人", en: "No creators found" })}</p><p className="mt-1 text-[10px] text-muted">{l({ zh: "请调整或清除筛选条件后重试。", en: "Try adjusting or clearing your filters." })}</p></div> : rows.map((creator) => { const profile = creatorProfiles[creator.id]; const channel = profile.channels[0]; const audience = profile.audienceProfiles[channel.channelId]; const selected = selectedIds.includes(creator.id); const PlatformIcon = channel.platform === "Instagram" ? Instagram : channel.platform === "TikTok" ? Music2 : Youtube; const platformTone = channel.platform === "Instagram" ? "text-[#B84D82]" : channel.platform === "TikTok" ? "text-[#343342]" : "text-[#D84A4A]"; return <article key={creator.id} className="grid min-h-[92px] grid-cols-[minmax(290px,1.65fr)_150px_170px_145px_145px] items-center border-b border-border/70 bg-white px-5 py-3 transition-colors last:border-b-0 hover:bg-[#FAFAFB]"><div className="flex min-w-0 items-center gap-3"><img src={profile.main.avatarUrl} alt="" className="h-12 w-12 shrink-0 rounded-full object-cover" /><div className="min-w-0"><div className="flex items-center gap-1.5"><h3 className="truncate text-[14px] font-semibold text-ink">{profile.main.creatorName}</h3>{channel.isVerified && <span className="text-[11px] font-semibold text-blue-text">✓</span>}<PlatformIcon className={`ml-0.5 h-3.5 w-3.5 ${platformTone}`} /></div><p className="mt-1 truncate text-[11px] text-muted">{"@"}{channel.username} · {profile.main.residentCountry}</p><div className="mt-2 flex flex-wrap gap-1">{profile.main.coreCategories.slice(0, 3).map((tag) => <span key={tag} className="rounded-full bg-[#F5F5F6] px-2 py-0.5 text-[9px] text-slate">{tag}</span>)}</div></div></div><div><p className="text-[14px] font-semibold text-ink">{Math.round(channel.followerCount / 1000)}K</p><p className="mt-1 text-[10px] text-emerald-600">+12% ↑</p></div><div className="text-[11px]"><p className="font-medium text-ink">{audience.geoDistribution[0].label} {audience.geoDistribution[0].percentage}%</p><p className="mt-1 text-muted">{audience.genderDistribution[0].label} {audience.genderDistribution[0].percentage}%</p></div><div><p className="text-[14px] font-semibold text-ink">ER {channel.avgEngagementRate}%</p><span className="mt-2 block h-1 w-16 overflow-hidden rounded-full bg-[#ECECEF]"><span className="block h-full w-2/3 rounded-full bg-slate" /></span></div><div className="flex justify-end gap-1"><button type="button" onClick={() => onToggle(creator.id)} className={`flex h-8 w-8 items-center justify-center rounded-[8px] transition ${selected ? "bg-[#F1EEFF] text-brand" : "text-slate hover:bg-[#F4F4F5] hover:text-ink"}`} aria-label={l({ zh: "收藏", en: "Save" })}><Heart className={`h-3.5 w-3.5 ${selected ? "fill-current" : ""}`} /></button><button type="button" className="flex h-8 w-8 items-center justify-center rounded-[8px] text-slate hover:bg-[#F4F4F5] hover:text-ink" aria-label={l({ zh: "加入名单", en: "Add to list" })}><ListPlus className="h-3.5 w-3.5" /></button><button type="button" onClick={() => onView(creator.id)} className="inline-flex h-8 items-center gap-1.5 rounded-[8px] border border-border bg-white px-2.5 text-[10px] font-medium text-slate hover:bg-[#F4F4F5] hover:text-ink"><Eye className="h-3.5 w-3.5" />{l({ zh: "查看", en: "View" })}</button></div></article>; })}
  </div></div>;
}

function CreatorDiscoveryGrid({ creators: rows, selectedIds, onToggle, onView }: { creators: typeof creators; selectedIds: string[]; onToggle: (id: string) => void; onView: (id: string) => void }) {
  const l = useLoc();
  return <div className="mt-3 grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{rows.map((creator) => { const profile = creatorProfiles[creator.id]; const channel = profile.channels[0]; const selected = selectedIds.includes(creator.id); return <article key={creator.id} className="rounded-[12px] border border-border bg-white p-4 transition-colors hover:bg-[#FAFAFB]"><div className="flex items-start gap-3"><img src={profile.main.avatarUrl} alt="" className="h-11 w-11 rounded-full object-cover" /><div className="min-w-0 flex-1"><div className="flex items-center gap-1.5"><h3 className="truncate text-[13px] font-semibold text-ink">{profile.main.creatorName}</h3>{channel.isVerified && <span className="text-[10px] font-semibold text-blue-text">✓</span>}</div><p className="mt-1 truncate text-[10px] text-muted">{"@"}{channel.username} · {channel.platform}</p></div><button type="button" onClick={() => onToggle(creator.id)} className={`flex h-8 w-8 shrink-0 items-center justify-center rounded-[8px] ${selected ? "bg-[#F1EEFF] text-brand" : "text-muted hover:bg-[#F4F4F5]"}`} aria-label={l({ zh: "收藏", en: "Save" })}><Heart className={`h-3.5 w-3.5 ${selected ? "fill-current" : ""}`} /></button></div><div className="mt-4 flex items-end justify-between"><div><p className="text-[15px] font-semibold text-ink">{Math.round(channel.followerCount / 1000)}K</p><p className="mt-1 text-[10px] text-muted">ER {channel.avgEngagementRate}%</p></div><button type="button" onClick={() => onView(creator.id)} className="inline-flex h-8 items-center gap-1.5 rounded-[8px] border border-border px-2.5 text-[10px] font-medium text-slate hover:bg-[#F4F4F5] hover:text-ink"><Eye className="h-3.5 w-3.5" />{l({ zh: "查看", en: "View" })}</button></div></article>; })}</div>;
}

function MoreCreatorFiltersDrawer({ filters, values, onChange, onReset, onApply, onClose }: { filters: { id: string; label: string; icon: React.ElementType; options: string[] }[]; values: Record<string, string>; onChange: (id: string, value: string) => void; onReset: () => void; onApply: () => void; onClose: () => void }) {
  const l = useLoc();
  return <div className="fixed inset-0 z-50 flex justify-end bg-ink/10" role="dialog" aria-modal="true" aria-label={l({ zh: "更多筛选", en: "More filters" })}><aside className="flex h-full w-full max-w-[420px] flex-col border-l border-border bg-white"><header className="flex h-16 items-center justify-between border-b border-border px-6"><h2 className="text-[15px] font-semibold text-ink">{l({ zh: "更多筛选", en: "More filters" })}</h2><button type="button" onClick={onClose} className="flex h-8 w-8 items-center justify-center rounded-[8px] text-muted hover:bg-[#F4F4F5] hover:text-ink" aria-label={l({ zh: "关闭", en: "Close" })}><X className="h-4 w-4" /></button></header><div className="flex-1 overflow-y-auto px-6 py-5"><p className="text-[10px] leading-5 text-muted">{l({ zh: "按需补充筛选条件，应用后将同步到达人列表。", en: "Add the conditions you need; they will apply to the creator list." })}</p><div className="mt-5 space-y-4">{filters.map((filter) => { const Icon = filter.icon; return <div key={filter.id}><div className="flex items-center gap-2 text-[11px] font-medium text-slate"><Icon className="h-3.5 w-3.5" />{filter.label}</div><div className="mt-2 flex flex-wrap gap-1.5">{filter.options.map((option) => <button key={option} type="button" onClick={() => onChange(filter.id, option)} className={`h-8 rounded-[7px] px-2.5 text-[10px] transition ${values[filter.id] === option ? "bg-[#F1EEFF] text-brand" : "bg-[#F5F5F6] text-slate hover:bg-[#ECECEF] hover:text-ink"}`}>{option}</button>)}</div></div>; })}</div></div><footer className="flex items-center justify-between border-t border-border px-6 py-4"><button type="button" onClick={onReset} className="text-[12px] text-slate hover:text-ink">{l({ zh: "重置", en: "Reset" })}</button><Button onClick={onApply} className="h-10 px-5">{l({ zh: "应用筛选", en: "Apply filters" })}</Button></footer></aside></div>;
}

function LegacySinglePlatformDirectoryPage({ activeTab, query, setQuery, platform, setPlatform, results, shortlisted, setShortlisted, detailCreator, setDetailCreatorId }: { activeTab: "marketplace" | "private"; onTabChange: (tab: "marketplace" | "private") => void; query: string; setQuery: (value: string) => void; platform: string; setPlatform: (value: string) => void; results: typeof creators; shortlisted: string[]; setShortlisted: React.Dispatch<React.SetStateAction<string[]>>; detailCreator: typeof creators[number] | null; setDetailCreatorId: (id: string | null) => void }) {
  const l = useLoc();
  const [activePlatform, setActivePlatform] = useState("Instagram");
  const [activeFilters, setActiveFilters] = useState<string[]>([]);
  const [advancedOpen, setAdvancedOpen] = useState(false);
  const [sort, setSort] = useState("Recommended");
  const marketplace = activeTab === "marketplace";
  useEffect(() => { if (marketplace) setPlatform(activePlatform); }, [activePlatform, marketplace, setPlatform]);
  const filterOptions = [
    { control: l({ zh: "国家 / 地区", en: "Country" }), value: l({ zh: "United States", en: "United States" }) },
    { control: l({ zh: "类型", en: "Category" }), value: l({ zh: "Beauty", en: "Beauty" }) },
    { control: l({ zh: "粉丝量", en: "Followers" }), value: "100K–500K" },
    { control: l({ zh: "互动率", en: "Engagement" }), value: "ER > 3%" },
    { control: l({ zh: "受众", en: "Audience" }), value: l({ zh: "Women 65%+", en: "Women 65%+" }) },
  ];
  const platforms = [
    { name: "Instagram", icon: Instagram, activeStyle: "bg-[#FDF1F7] text-[#C13584]", idleStyle: "text-[#A25A85]" },
    { name: "TikTok", icon: Music2, activeStyle: "bg-[#F1F1F4] text-[#1B1B27]", idleStyle: "text-[#73738A]" },
    { name: "YouTube", icon: Youtube, activeStyle: "bg-[#FFF2F2] text-[#E13A3A]", idleStyle: "text-[#C36363]" },
  ];
  const toggleFilter = (value: string) => setActiveFilters((items) => items.includes(value) ? items.filter((item) => item !== value) : [...items, value]);
  const toggleCreator = (id: string) => setShortlisted((items) => items.includes(id) ? items.filter((item) => item !== id) : [...items, id]);
  if (!marketplace) return <main className="min-h-full bg-white px-6 py-6 lg:px-10"><div className="mx-auto w-full max-w-[1440px]"><PrivateCreatorsView /></div></main>;
  return <main className="min-h-full bg-white px-6 py-6 lg:px-10"><div className="mx-auto w-full max-w-[1440px]">
    <nav className="flex items-end gap-1 border-b border-border" aria-label={l({ zh: "媒体平台", en: "Media platforms" })}>{platforms.map(({ name, icon: Icon, activeStyle, idleStyle }) => { const active = activePlatform === name; return <button key={name} type="button" onClick={() => { setActivePlatform(name); setPlatform(name); }} className={`relative flex h-[52px] items-center gap-2 px-3.5 transition-colors ${active ? "text-ink" : "text-muted hover:text-slate"}`}><span className={`flex h-7 w-7 items-center justify-center rounded-[9px] ${active ? activeStyle : `bg-transparent ${idleStyle}`}`}><Icon className="h-4 w-4" strokeWidth={active ? 2.25 : 1.85} /></span><span className={`tracking-[-0.025em] ${active ? "font-serif text-[16px] font-semibold italic" : "text-[13px] font-medium"}`}>{name}</span>{active && <span className="absolute inset-x-3.5 bottom-0 h-0.5 bg-ink" />}</button>; })}</nav>
    <section className="pt-5"><div className="relative w-full max-w-[620px]"><Search className="pointer-events-none absolute left-4 top-1/2 h-4 w-4 -translate-y-1/2 text-muted" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={l({ zh: "搜索达人、用户名或关键词", en: "Search creators, usernames or keywords" })} className="h-11 w-full rounded-[11px] border border-border bg-white pl-11 pr-4 text-[12px] text-ink outline-none transition placeholder:text-muted focus:border-brand/35 focus:shadow-[0_5px_16px_rgba(90,34,255,0.06)]" /></div>
      <div className="mt-3 flex flex-wrap items-center gap-2">{filterOptions.map(({ control, value }) => { const applied = activeFilters.includes(value); return <button key={control} type="button" onClick={() => toggleFilter(value)} className={`flex h-9 items-center gap-2 rounded-[9px] border px-3 text-[11px] transition ${applied ? "border-brand/25 bg-[#F4F1FF] text-brand" : "border-border bg-white text-slate hover:border-[#D6D4DD] hover:text-ink"}`}><span>{applied ? value : control}</span><ChevronDown className="h-3.5 w-3.5" /></button>; })}<button type="button" onClick={() => setAdvancedOpen((open) => !open)} className={`flex h-9 items-center gap-1.5 rounded-[9px] border px-3 text-[11px] transition ${advancedOpen ? "border-brand/25 bg-[#F4F1FF] text-brand" : "border-border bg-white text-slate hover:text-ink"}`}><Filter className="h-3.5 w-3.5" />{l({ zh: "更多筛选", en: "More filters" })}</button></div>
      {advancedOpen && <div className="mt-2.5 grid gap-2 rounded-[11px] border border-border bg-[#FAFAFB] p-3 sm:grid-cols-2 lg:grid-cols-4">{[l({ zh: "语言", en: "Language" }), l({ zh: "性别", en: "Gender" }), l({ zh: "平均播放", en: "Average views" }), l({ zh: "增长率", en: "Growth rate" }), l({ zh: "合作邮箱", en: "Email available" }), l({ zh: "预估合作报价", en: "Est. collaboration rate" }), l({ zh: "品牌安全", en: "Brand safety" })].map((item) => <button key={item} className="flex h-8 items-center justify-between rounded-[8px] border border-border bg-white px-2.5 text-left text-[10px] text-slate hover:text-ink">{item}<ChevronDown className="h-3 w-3 text-muted" /></button>)}</div>}
      {activeFilters.length > 0 && <div className="mt-3 flex flex-wrap items-center gap-1.5"><span className="mr-1 text-[10px] text-muted">{l({ zh: "已应用", en: "Active" })}</span>{activeFilters.map((item) => <button key={item} type="button" onClick={() => toggleFilter(item)} className="inline-flex items-center gap-1 rounded-full bg-[#F4F4F5] px-2.5 py-1 text-[10px] text-slate hover:bg-[#ECECEF]">{item}<X className="h-3 w-3" /></button>)}<button type="button" onClick={() => setActiveFilters([])} className="ml-1 text-[10px] text-slate underline-offset-2 hover:text-ink hover:underline">{l({ zh: "清除全部", en: "Clear all" })}</button></div>}
    </section>
    <section className="mt-6"><div className="flex items-center gap-3"><strong className="text-[17px] font-semibold tracking-[-0.02em] text-ink">{results.length.toLocaleString()} {l({ zh: "位达人", en: "creators" })}</strong><span className="text-[10px] text-muted">{l({ zh: "根据当前条件更新", en: "Updated by current filters" })}</span><label className="ml-auto flex h-8 items-center gap-2 rounded-[8px] border border-border bg-white px-2.5 text-[10px] text-slate">{l({ zh: "排序：", en: "Sort by:" })}<select value={sort} onChange={(event) => setSort(event.target.value)} className="appearance-none bg-transparent pr-1 font-medium text-ink outline-none"><option>Recommended</option><option>Followers</option><option>Engagement</option><option>Average Views</option><option>Growth</option></select><ChevronDown className="pointer-events-none -ml-3 h-3.5 w-3.5 text-muted" /></label></div>
      <MarketplaceCreatorTable creators={results} selectedIds={shortlisted} onToggle={toggleCreator} onView={setDetailCreatorId} />
    </section>{detailCreator && <CreatorProfileDrawer creator={detailCreator} onClose={() => setDetailCreatorId(null)} />}
  </div></main>;
}

function LegacyMarketplaceCreatorTable({ creators: rows, selectedIds, onToggle, onView }: { creators: typeof creators; selectedIds: string[]; onToggle: (id: string) => void; onView: (id: string) => void }) {
  const l = useLoc();
  const allSelected = rows.length > 0 && rows.every((creator) => selectedIds.includes(creator.id));
  const toggleAll = () => rows.forEach((creator) => { if (allSelected ? selectedIds.includes(creator.id) : !selectedIds.includes(creator.id)) onToggle(creator.id); });
  return <div className="mt-4 overflow-x-auto rounded-[12px] border border-border bg-white"><div className="min-w-[1080px]">
    {selectedIds.length > 0 && <div className="flex items-center gap-2 border-b border-border bg-[#FAF9FF] px-4 py-2.5"><strong className="text-[11px] font-medium text-ink">{selectedIds.length} {l({ zh: "已选择", en: "selected" })}</strong><button className="ml-2 inline-flex h-7 items-center gap-1.5 rounded-[7px] border border-border bg-white px-2.5 text-[10px] text-slate hover:text-ink"><ListPlus className="h-3.5 w-3.5" />{l({ zh: "加入列表", en: "Add to list" })}</button><button className="inline-flex h-7 items-center gap-1.5 rounded-[7px] border border-border bg-white px-2.5 text-[10px] text-slate hover:text-ink"><Download className="h-3.5 w-3.5" />{l({ zh: "导出", en: "Export" })}</button><button className="inline-flex h-7 items-center gap-1.5 rounded-[7px] border border-border bg-white px-2.5 text-[10px] text-slate hover:text-ink"><Send className="h-3.5 w-3.5" />{l({ zh: "建联", en: "Outreach" })}</button></div>}
    <div className="grid grid-cols-[40px_minmax(270px,1.55fr)_150px_160px_155px_145px_155px] items-center border-b border-border bg-[#F7F7F8] px-4 py-3 text-[9px] font-medium uppercase tracking-[0.07em] text-muted"><label className="flex items-center"><input aria-label={l({ zh: "全选", en: "Select all" })} checked={allSelected} onChange={toggleAll} type="checkbox" className="h-3.5 w-3.5 accent-[#5A22FF]" /></label><span>{l({ zh: "达人", en: "Creator" })}</span><span>{l({ zh: "触达", en: "Reach" })}</span><span>{l({ zh: "受众", en: "Audience" })}</span><span>{l({ zh: "表现", en: "Performance" })}</span><span>{l({ zh: "预估报价", en: "Est. rate" })}</span><span className="text-right">{l({ zh: "操作", en: "Actions" })}</span></div>
    {/*
    {rows.length === 0 ? <div className="px-5 py-16 text-center"><p className="text-[13px] font-medium text-ink">{l({ zh: "未找到达人", en: "No creators found" })}</p><p className="mt-1 text-[10px] text-muted">{l({ zh: "请调整或清除筛选条件后重试。", en: "Try adjusting or clearing your filters." })}</p></div> : rows.map((creator) => { const profile = creatorProfiles[creator.id]; const channel = profile.channels[0]; const audience = profile.audienceProfiles[channel.channelId]; const selected = selectedIds.includes(creator.id); return <article key={creator.id} className={`grid min-h-[88px] grid-cols-[40px_minmax(270px,1.55fr)_150px_160px_155px_145px_155px] items-center border-b border-border/70 px-4 py-3 transition-colors last:border-b-0 hover:bg-[#FAFAFB] ${selected ? "bg-[#FAF9FF]" : "bg-white"}`}><label className="flex items-center"><input aria-label={`${l({ zh: "选择", en: "Select" })} ${profile.main.creatorName}`} checked={selected} onChange={() => onToggle(creator.id)} type="checkbox" className="h-3.5 w-3.5 accent-[#5A22FF]" /></label><div className="flex min-w-0 items-center gap-3"><img src={profile.main.avatarUrl} alt="" className="h-11 w-11 shrink-0 rounded-full object-cover" /><div className="min-w-0"><div className="flex items-center gap-1.5"><h3 className="truncate text-[12px] font-semibold text-ink">{profile.main.creatorName}</h3>{channel.isVerified && <span className="text-[10px] font-semibold text-blue-text">✓</span></div><p className="mt-0.5 truncate text-[9.5px] text-muted">@{channel.username} · {profile.main.residentCountry}</p><div className="mt-1.5 flex flex-wrap gap-1">{profile.main.coreCategories.slice(0, 2).map((tag) => <span key={tag} className="rounded-full bg-[#F4F4F5] px-1.5 py-0.5 text-[8px] text-slate">{tag}</span>)}</div></div></div><div><p className="text-[11px] font-medium text-ink">{Math.round(channel.followerCount / 1000)}K <span className="font-normal text-muted">{l({ zh: "粉丝", en: "followers" })}</span></p><p className="mt-1 text-[9px] text-muted">{Math.round(channel.avgViews / 1000)}K {l({ zh: "平均播放", en: "avg. views" })}</p></div><div className="text-[10px]"><p className="font-medium text-ink">{audience.geoDistribution[0].label} {audience.geoDistribution[0].percentage}%</p><p className="mt-1 text-muted">{audience.genderDistribution[0].label} {audience.genderDistribution[0].percentage}%</p></div><div className="text-[10px]"><p className="font-medium text-ink">ER {channel.avgEngagementRate}%</p><p className="mt-1 text-muted">{l({ zh: "真实性", en: "Authenticity" })} {profile.main.authenticityScore}%</p></div><div><p className="text-[11px] font-semibold text-ink">{profile.commercialInfo.estimatedPriceRange}</p><p className="mt-1 text-[9px] text-muted">CPM ${profile.commercialInfo.avgCpm}</p></div><div className="flex justify-end gap-1"><button type="button" onClick={() => onToggle(creator.id)} className={`flex h-8 w-8 items-center justify-center rounded-[8px] transition ${selected ? "bg-[#F1EEFF] text-brand" : "text-slate hover:bg-[#F4F4F5] hover:text-ink"}`} aria-label={l({ zh: "保存", en: "Save" })}><Heart className={`h-3.5 w-3.5 ${selected ? "fill-current" : ""}`} /></button><button type="button" className="flex h-8 w-8 items-center justify-center rounded-[8px] text-slate hover:bg-[#F4F4F5] hover:text-ink" aria-label={l({ zh: "加入列表", en: "Add to list" })}><ListPlus className="h-3.5 w-3.5" /></button><button type="button" onClick={() => onView(creator.id)} className="inline-flex h-8 items-center gap-1.5 rounded-[8px] bg-[#F4F4F5] px-2.5 text-[10px] font-medium text-slate hover:bg-[#ECECEF] hover:text-ink"><Eye className="h-3.5 w-3.5" />{l({ zh: "查看", en: "View" })}</button></div></article>; })}
    */}
    {rows.map((creator) => { const profile = creatorProfiles[creator.id]; const channel = profile.channels[0]; const audience = profile.audienceProfiles[channel.channelId]; const selected = selectedIds.includes(creator.id); return <article key={creator.id} className={`grid min-h-[88px] grid-cols-[40px_minmax(270px,1.55fr)_150px_160px_155px_145px_155px] items-center border-b border-border/70 px-4 py-3 transition-colors last:border-b-0 hover:bg-[#FAFAFB] ${selected ? "bg-[#FAF9FF]" : "bg-white"}`}><label className="flex items-center"><input aria-label={`${l({ zh: "选择", en: "Select" })} ${profile.main.creatorName}`} checked={selected} onChange={() => onToggle(creator.id)} type="checkbox" className="h-3.5 w-3.5 accent-[#5A22FF]" /></label><div className="flex min-w-0 items-center gap-3"><img src={profile.main.avatarUrl} alt="" className="h-11 w-11 shrink-0 rounded-full object-cover" /><div className="min-w-0"><div className="flex items-center gap-1.5"><h3 className="truncate text-[12px] font-semibold text-ink">{profile.main.creatorName}</h3>{channel.isVerified && <span className="text-[10px] font-semibold text-blue-text">✓</span>}</div><p className="mt-0.5 truncate text-[9.5px] text-muted">{"@"}{channel.username} · {profile.main.residentCountry}</p><div className="mt-1.5 flex flex-wrap gap-1">{profile.main.coreCategories.slice(0, 2).map((tag) => <span key={tag} className="rounded-full bg-[#F4F4F5] px-1.5 py-0.5 text-[8px] text-slate">{tag}</span>)}</div></div></div><div><p className="text-[11px] font-medium text-ink">{Math.round(channel.followerCount / 1000)}K <span className="font-normal text-muted">{l({ zh: "粉丝", en: "followers" })}</span></p><p className="mt-1 text-[9px] text-muted">{Math.round(channel.avgViews / 1000)}K {l({ zh: "平均播放", en: "avg. views" })}</p></div><div className="text-[10px]"><p className="font-medium text-ink">{audience.geoDistribution[0].label} {audience.geoDistribution[0].percentage}%</p><p className="mt-1 text-muted">{audience.genderDistribution[0].label} {audience.genderDistribution[0].percentage}%</p></div><div className="text-[10px]"><p className="font-medium text-ink">ER {channel.avgEngagementRate}%</p><p className="mt-1 text-muted">{l({ zh: "真实性", en: "Authenticity" })} {profile.main.authenticityScore}%</p></div><div><p className="text-[11px] font-semibold text-ink">{profile.commercialInfo.estimatedPriceRange}</p><p className="mt-1 text-[9px] text-muted">CPM ${profile.commercialInfo.avgCpm}</p></div><div className="flex justify-end gap-1"><button type="button" onClick={() => onToggle(creator.id)} className={`flex h-8 w-8 items-center justify-center rounded-[8px] transition ${selected ? "bg-[#F1EEFF] text-brand" : "text-slate hover:bg-[#F4F4F5] hover:text-ink"}`} aria-label={l({ zh: "保存", en: "Save" })}><Heart className={`h-3.5 w-3.5 ${selected ? "fill-current" : ""}`} /></button><button type="button" className="flex h-8 w-8 items-center justify-center rounded-[8px] text-slate hover:bg-[#F4F4F5] hover:text-ink" aria-label={l({ zh: "加入列表", en: "Add to list" })}><ListPlus className="h-3.5 w-3.5" /></button><button type="button" onClick={() => onView(creator.id)} className="inline-flex h-8 items-center gap-1.5 rounded-[8px] bg-[#F4F4F5] px-2.5 text-[10px] font-medium text-slate hover:bg-[#ECECEF] hover:text-ink"><Eye className="h-3.5 w-3.5" />{l({ zh: "查看", en: "View" })}</button></div></article>; })}
  </div></div>;
}

function LegacyPlatformDirectoryPage({ activeTab, query, setQuery, platform, setPlatform, results, shortlisted, setShortlisted, detailCreator, setDetailCreatorId }: { activeTab: "marketplace" | "private"; onTabChange: (tab: "marketplace" | "private") => void; query: string; setQuery: (value: string) => void; platform: string; setPlatform: (value: string) => void; results: typeof creators; shortlisted: string[]; setShortlisted: React.Dispatch<React.SetStateAction<string[]>>; detailCreator: typeof creators[number] | null; setDetailCreatorId: (id: string | null) => void }) {
  const l = useLoc();
  const [activePlatform, setActivePlatform] = useState("Instagram");
  const marketplace = activeTab === "marketplace";
  useEffect(() => { if (marketplace) setPlatform(activePlatform); }, [activePlatform, marketplace, setPlatform]);
  const toggle = (creatorId: string) => setShortlisted((all) => all.includes(creatorId) ? all.filter((id) => id !== creatorId) : [...all, creatorId]);
  const selectPlatform = (value: string) => { setActivePlatform(value); setPlatform(value); };
  const platformOptions = [
    { name: "Instagram", icon: Instagram, activeStyle: "bg-[#FDF1F7] text-[#C13584]", inactiveStyle: "text-[#C13584]" },
    { name: "TikTok", icon: Music2, activeStyle: "bg-[#F1F1F4] text-[#1B1B27]", inactiveStyle: "text-[#67677A]" },
    { name: "YouTube", icon: Youtube, activeStyle: "bg-[#FFF2F2] text-[#E13A3A]", inactiveStyle: "text-[#D44747]" },
  ];
  return <main className="min-h-full bg-white px-6 py-6 lg:px-10"><div className="mx-auto w-full max-w-[1440px]">{marketplace ? <><nav className="flex items-end gap-1 border-b border-border" aria-label={l({ zh: "媒体平台", en: "Media platforms" })}>{platformOptions.map(({ name, icon: Icon, activeStyle, inactiveStyle }) => { const active = activePlatform === name; return <button key={name} type="button" onClick={() => selectPlatform(name)} className={`relative flex h-[54px] items-center gap-2.5 px-3.5 transition-colors ${active ? "text-ink" : "text-muted hover:text-slate"}`}><span className={`flex h-7 w-7 items-center justify-center rounded-[9px] transition-colors ${active ? activeStyle : `bg-transparent ${inactiveStyle}`}`}><Icon className="h-4 w-4" strokeWidth={active ? 2.25 : 1.9} /></span><span className={`tracking-[-0.035em] ${active ? "font-serif text-[16px] font-semibold italic" : "text-[13px] font-medium"}`}>{name}</span>{active && <span className="absolute inset-x-3.5 bottom-0 h-0.5 bg-ink" />}</button>; })}</nav><section className="mt-5"><div className="relative max-w-[420px]"><Search className="pointer-events-none absolute left-3.5 top-1/2 h-4 w-4 -translate-y-1/2 text-muted" /><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder={l({ zh: "搜索达人名称、账号或关键词", en: "Search creators, usernames or keywords" })} className="h-10 w-full rounded-[10px] bg-[#F4F4F5] pl-10 pr-3 text-[11px] text-ink outline-none placeholder:text-muted focus:bg-white focus:ring-1 focus:ring-brand/25" /></div><div className="mt-3 flex flex-wrap items-center gap-2.5"><span className="mr-1 flex items-center gap-1.5 text-[10px] font-medium text-slate"><SlidersHorizontal className="h-3.5 w-3.5" />{l(L.filters)}</span><StaticDrop label={l(L.country)} /><StaticDrop label={l(L.category)} /><StaticDrop label={l(L.followers)} /><StaticDrop label={l({ zh: "互动率", en: "Engagement rate" })} /></div><div className="mt-3 flex flex-wrap items-center gap-2.5"><span className="mr-1 text-[10px] font-medium text-slate">{l({ zh: "排序方式", en: "Sort by" })}</span>{[l({ zh: "综合推荐", en: "Recommended" }), l({ zh: "粉丝量", en: "Followers" }), l({ zh: "互动率", en: "Engagement" }), l({ zh: "平均播放", en: "Avg. views" })].map((item, index) => <button key={item} type="button" className={`rounded-[8px] px-3 py-1.5 text-[10px] ${index === 0 ? "bg-[#F1EEFF] text-brand" : "bg-[#F5F5F6] text-slate hover:text-ink"}`}>{item}</button>)}</div></section><div className="mt-7 flex items-center gap-3"><strong className="text-[16px] font-semibold text-ink">{results.length} {l(L.creators)}</strong><span className="text-[10px] text-muted">{l({ zh: "根据筛选条件更新", en: "Updated by your filters" })}</span><button type="button" className="ml-auto flex h-8 items-center gap-1.5 rounded-[8px] bg-[#F4F4F5] px-3 text-[10px] text-slate">{l(L.sort)}<ChevronDown className="h-3.5 w-3.5" /></button></div><DiscoverCreatorTable creators={results} shortlisted={shortlisted} onToggle={toggle} onView={setDetailCreatorId} /></> : <PrivateCreatorsView />}{detailCreator && <CreatorProfileDrawer creator={detailCreator} onClose={() => setDetailCreatorId(null)} />}</div></main>;
}

